// Extrae texto, remitente y datos de respuesta del payload de WhatsApp.
// Ignora eventos de estado (sent/delivered/read), que no traen "messages".

// Lista blanca opcional: números con código de país y sin '+', ej. '5493511234567'.
// Vacía = acepta mensajes de cualquier número.
const NUMEROS_PERMITIDOS = [];

const fechaHoy = $now.setZone('America/Argentina/Cordoba').toFormat('dd-MM-yyyy');
const salida = [];

for (const item of $input.all()) {
  const j = item.json;
  const valores = Array.isArray(j.entry)
    ? j.entry.flatMap(e => (e.changes || []).map(c => c.value || {}))
    : [j];

  for (const v of valores) {
    const msg = v.messages && v.messages[0];
    if (!msg) continue;

    const remitente = String(msg.from || '');
    if (NUMEROS_PERMITIDOS.length && !NUMEROS_PERMITIDOS.includes(remitente)) continue;

    salida.push({
      json: {
        texto: msg.type === 'text' ? String((msg.text && msg.text.body) || '').trim() : '',
        tipo_mensaje: msg.type || '',
        remitente,
        nombre: (v.contacts && v.contacts[0] && v.contacts[0].profile && v.contacts[0].profile.name) || '',
        phone_number_id: (v.metadata && v.metadata.phone_number_id) || '',
        message_id: msg.id || '',
        fecha_hoy: fechaHoy,
      },
    });
  }
}

return salida;

// Limpia la respuesta de Claude (bloques markdown, texto extra) y la parsea de forma segura.
// Si algo no cierra, marca el registro como INVALIDO en vez de romper el flujo.
const origen = $('Extraer datos del mensaje').item.json;
const r = $json;

let crudo = '';
if (typeof r.merged_response === 'string') crudo = r.merged_response;
else if (Array.isArray(r.content)) crudo = r.content.filter(c => c && c.type === 'text').map(c => c.text).join('\n');
else if (typeof r.text === 'string') crudo = r.text;
else if (typeof r.output === 'string') crudo = r.output;

let limpio = String(crudo).replace(/```(?:json)?/gi, '').trim();
const ini = limpio.indexOf('{');
const fin = limpio.lastIndexOf('}');
if (ini !== -1 && fin > ini) limpio = limpio.slice(ini, fin + 1);

let d = {};
let errorParseo = '';
try {
  d = JSON.parse(limpio);
  if (!d || typeof d !== 'object' || Array.isArray(d)) throw new Error('La respuesta no es un objeto JSON');
} catch (e) {
  d = {};
  errorParseo = e.message;
}

const CATEGORIAS = [
  'Alimentación / Supermercado', 'Salidas / Ocio', 'Servicios y Suscripciones', 'Salud y Deporte',
  'Transporte / Vehículo', 'Indumentaria / Compras', 'Vivienda / Hogar', 'Educación / Cursos',
  'Ingresos / Sueldo / Extras', 'Otros',
];

const tipoCrudo = String(d.tipo || '').toUpperCase().trim();
let tipo = ['GASTO', 'INGRESO'].includes(tipoCrudo) ? tipoCrudo : 'INVALIDO';

// Acepta número o texto tipo "15.000", "15.000,50" o "$ 2500"
let monto = d.monto;
if (typeof monto === 'string') {
  monto = monto.replace(/[^\d,.-]/g, '').replace(/\.(?=\d{3}(\D|$))/g, '').replace(',', '.');
}
monto = Number(monto);
if (tipo !== 'INVALIDO' && !(Number.isFinite(monto) && monto > 0)) tipo = 'INVALIDO';
monto = tipo === 'INVALIDO' ? 0 : Math.round(monto * 100) / 100;

const moneda = String(d.moneda || '').toUpperCase().includes('USD') ? 'USD' : 'ARS';
const fecha = /^\d{2}-\d{2}-\d{4}$/.test(String(d.fecha || '')) ? d.fecha : origen.fecha_hoy;
const categoria = CATEGORIAS.includes(d.categoria) ? d.categoria : 'Otros';

let montoTexto = String(monto);
try {
  montoTexto = monto.toLocaleString('es-AR', { maximumFractionDigits: 2 });
} catch (e) {}

return {
  json: {
    fecha,
    tipo,
    monto,
    moneda,
    categoria,
    descripcion: String(d.descripcion || '').trim(),
    metodo_pago: String(d.metodo_pago || '').trim() || 'No especificado',
    notas: String(d.notas || '').trim(),
    monto_texto: montoTexto,
    remitente: origen.remitente,
    phone_number_id: origen.phone_number_id,
    texto_original: origen.texto,
    error_parseo: errorParseo,
    respuesta_cruda: crudo,
  },
};

